_ROWS['Search contacts'] = ('Buscar contactos', 'Cerca contactes', 'Поиск контактов', 'Szukaj kontaktów', 'Пошук контактів', 'Pesquisar contactos', 'Cerca contatti', 'Rechercher des contacts')  # 1.4.0.1

LANGUAGES = ('es', 'ca', 'ru', 'pl', 'uk', 'pt', 'it', 'fr')
VALUES = {code: {key: row[index] for key, row in _ROWS.items()} for index, code in enumerate(LANGUAGES)}


def extend(catalogues):
    for code, values in VALUES.items():
        catalogues.setdefault(code, {}).update(values)
    catalogues.setdefault('ca-valencia', {}).update(VALUES['ca'])
    # Remaining in-catalogue languages; the on-demand packs (ar, nl, …) carry
    # the same labels inside tg_ascii/locales/*.json.
    from .translations_v14_world import ORDER, PACK_LANGUAGES, values
    for code in ORDER:
        if code not in PACK_LANGUAGES and isinstance(catalogues.get(code), dict):
            catalogues[code].update(values(code))
    for variant in ('es-x-chileno', 'es-x-andaluz'):
        if variant in catalogues:
            for key, value in VALUES['es'].items():
                catalogues[variant].setdefault(key, value)


